import React,{useEffect,useMemo,useRef,useState} from 'react';
import {createPortal} from 'react-dom';
import {supabase} from './supabase';
import {jsPDF} from 'jspdf';
import * as XLSX from 'xlsx';
import './planning.css';

const uid=()=>crypto.randomUUID();
const dimensionOption=(title='')=>({id:uid(),title,days:'',team_size:'',notes:''});
const toLocalDateTime=value=>{if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value).slice(0,16);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const toIsoDateTime=value=>{if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?value:date.toISOString()};
const roles=['Liderança geral','Mesa','Frios','Líder de pré-contagem','Coordenação do turno noturno','Coordenador líder','Coordenador','Apoio','Conferente','Líder de perecíveis'];
const activities=['Coleta das gavetas','Coleta de picking','Coleta de aéreo','Coleta de subaéreo','Coleta de produtos para pesagem/balança','Mapeamento do piso de vendas','Auditoria e ajuste das gavetas'];
const equipment=['Empilhadeira','Escada','Rádio comunicador','Coletor de dados','Notebook','Impressora','Balança','EPI perecível','Ônibus','Micro-ônibus','Van'];
const checklistLabels={preInventory:'Visita pré-inventário',planning:'Planejamento',final:'Aprovação final'};
const planningColumns=[{key:'received',label:'Entrada',statuses:['received']},{key:'dimensioning',label:'Dimensionamento',statuses:['awaiting_dimensioning']},{key:'ti',label:'TI / Datas',statuses:['awaiting_ti','awaiting_dates']},{key:'planning',label:'Em planejamento',statuses:['planning']},{key:'done',label:'Concluídos',statuses:['confirmed']}];
const planningStatus={received:'Entrada',awaiting_dimensioning:'Dimensionamento',awaiting_ti:'TI / Datas',awaiting_dates:'Datas enviadas',planning:'Planejamento',confirmed:'Concluído'};
const responsibilityRows=()=>['Liderança geral','Mesa','Frios','Líder de pré-contagem','Coordenação do turno noturno'].map(role=>({id:uid(),role,person:'',notes:''}));
const area=(kind='Depósito')=>{const base={id:uid(),name:kind,shift:'',startsAt:'',headcount:'',notes:'',roles:[],activities:[]};if(kind==='Depósito')return {...base,roles:[{id:uid(),role:'Coordenador líder',count:'',names:''},{id:uid(),role:'Coordenador',count:'',names:''},{id:uid(),role:'Apoio',count:'',names:''},{id:uid(),role:'Conferente',count:'',names:''}],activities:['Coleta das gavetas','Coleta de picking','Coleta de aéreo','Coleta de subaéreo'].map(name=>({id:uid(),name,notes:''}))};if(kind==='Câmaras')return {...base,roles:[{id:uid(),role:'Líder de perecíveis',count:'',names:''},{id:uid(),role:'Conferente',count:'',names:''}],activities:['Coleta de aéreo','Coleta de subaéreo','Coleta de picking','Coleta de produtos para pesagem/balança'].map(name=>({id:uid(),name,notes:''}))};if(kind==='Coordenação')return {...base,roles:[{id:uid(),role:'Coordenação',count:'',names:''}],activities:[]};if(kind==='Divisão da equipe')return {...base,roles:[{id:uid(),role:'Conferente',count:'',names:''}],activities:[]};return base};
const day=(date='')=>({id:uid(),date,headcount:'',notes:'',areas:[]});
const initial=()=>({dynamicBlocks:{},store:{unit:'',preCountEnabled:false,preStart:'',preEnd:'',inventoryStart:'',inventoryEnd:'',headcount:''},responsibilities:responsibilityRows(),logistics:{transports:[],accommodations:[],notes:''},clientEquipment:{rows:[],notes:''},contagemEquipment:{rows:[],notes:''},preCount:{rows:[],notes:''},days:[],completedBlocks:{},checklists:{preInventory:[{id:uid(),label:'Visita pré-inventário realizada',done:false},{id:uid(),label:'Layout, áreas e acessos validados',done:false},{id:uid(),label:'Contato da loja e responsáveis confirmados',done:false}],planning:[{id:uid(),label:'Responsáveis definidos',done:false},{id:uid(),label:'Logística revisada',done:false},{id:uid(),label:'Equipamentos confirmados',done:false},{id:uid(),label:'Horários de alimentação definidos',done:false}],final:[{id:uid(),label:'Planejamento revisado',done:false},{id:uid(),label:'Pendências críticas resolvidas',done:false},{id:uid(),label:'Aprovação do supervisor',done:false}]}});
const merge=(value)=>{const defaults=initial();const days=Array.isArray(value?.days)?value.days.map(dayItem=>({...day(),...dayItem,areas:Array.isArray(dayItem?.areas)?dayItem.areas.map(areaItem=>({...areaItem,roles:Array.isArray(areaItem?.roles)?areaItem.roles:[],activities:Array.isArray(areaItem?.activities)?areaItem.activities:[]})):[]})):[];return {...defaults,...(value||{}),dynamicBlocks:{...defaults.dynamicBlocks,...(value?.dynamicBlocks||{})},completedBlocks:{...defaults.completedBlocks,...(value?.completedBlocks||{})},responsibilities:Array.isArray(value?.responsibilities)&&value.responsibilities.length?value.responsibilities:defaults.responsibilities,store:{...defaults.store,...(value?.store||{})},logistics:{...defaults.logistics,...(value?.logistics||{}),transports:Array.isArray(value?.logistics?.transports)?value.logistics.transports:[],accommodations:Array.isArray(value?.logistics?.accommodations)?value.logistics.accommodations:[]},clientEquipment:{...defaults.clientEquipment,...(value?.clientEquipment||{}),rows:Array.isArray(value?.clientEquipment?.rows)?value.clientEquipment.rows:[]},contagemEquipment:{...defaults.contagemEquipment,...(value?.contagemEquipment||{}),rows:Array.isArray(value?.contagemEquipment?.rows)?value.contagemEquipment.rows:[]},preCount:{...defaults.preCount,...(value?.preCount||{}),rows:Array.isArray(value?.preCount?.rows)?value.preCount.rows:[]},days,checklists:{preInventory:Array.isArray(value?.checklists?.preInventory)?value.checklists.preInventory:defaults.checklists.preInventory,planning:Array.isArray(value?.checklists?.planning)?value.checklists.planning:defaults.checklists.planning,final:Array.isArray(value?.checklists?.final)?value.checklists.final:defaults.checklists.final}}};

const hasValue=value=>value!==null&&value!==undefined&&(typeof value!=='string'||value.trim()!=='');
const isPositive=value=>hasValue(value)&&Number.isInteger(Number(value))&&Number(value)>0;
const hasRowData=(item,ignored=['id'])=>Boolean(item&&Object.entries(item).some(([key,value])=>!ignored.includes(key)&&(Array.isArray(value)?value.length>0:typeof value==='boolean'?value:hasValue(value))));
const addCheck=(checks,label,ok)=>checks.push({label,ok:Boolean(ok)});
const makeBlock=(key,label,checks,applicable=true)=>{const completed=checks.filter(check=>check.ok).length;const percentage=!applicable||!checks.length?100:Math.round(completed/checks.length*100);return {key,label,checks,applicable,percentage,issues:applicable?checks.filter(check=>!check.ok).map(check=>check.label):[]}};
const dateIsBetween=(date,start,end)=>!date||!start||!end||(date>=start&&date<=end);
const unique=list=>[...new Set(list)];

export function auditPlanning(content,blockDefinitions=[]){
  const blocks=[];
  const validationErrors=[];
  const store=content.store||{};

  const storeChecks=[];
  addCheck(storeChecks,'Informar a unidade da loja.',hasValue(store.unit));
  addCheck(storeChecks,'Informar uma quantidade positiva para o efetivo geral.',isPositive(store.headcount));
  addCheck(storeChecks,'Informar a data inicial do inventário.',hasValue(store.inventoryStart));
  addCheck(storeChecks,'Informar a data final do inventário.',hasValue(store.inventoryEnd));
  addCheck(storeChecks,'Manter o início do inventário anterior ou igual ao fim.',store.inventoryStart&&store.inventoryEnd&&store.inventoryStart<=store.inventoryEnd);
  blocks.push(makeBlock('store','Loja',storeChecks));
  if(store.inventoryStart&&store.inventoryEnd&&store.inventoryStart>store.inventoryEnd)validationErrors.push('A data inicial do inventário deve ser anterior ou igual à data final.');
  if(hasValue(store.headcount)&&!isPositive(store.headcount))validationErrors.push('O efetivo geral deve ser maior que zero.');

  const responsibilityChecks=[];
  const responsibilities=Array.isArray(content.responsibilities)?content.responsibilities:[];
  addCheck(responsibilityChecks,'Cadastrar ao menos um responsável com função e nome.',responsibilities.some(row=>hasValue(row.role)&&hasValue(row.person)));
  responsibilities.forEach((row,index)=>{
    const description=row.role?.trim()||`linha ${index+1}`;
    addCheck(responsibilityChecks,`Informar a função do responsável na ${description}.`,hasValue(row.role));
    addCheck(responsibilityChecks,`Informar o responsável por ${description}.`,hasValue(row.person));
  });
  blocks.push(makeBlock('responsibilities','Responsáveis',responsibilityChecks));

  const logistics=content.logistics||{transports:[],accommodations:[],notes:''};
  const transports=Array.isArray(logistics.transports)?logistics.transports:[];
  const accommodations=Array.isArray(logistics.accommodations)?logistics.accommodations:[];
  const logisticsApplicable=transports.length>0||accommodations.length>0||hasValue(logistics.notes);
  const operationalStart=store.preCountEnabled&&store.preStart?store.preStart:store.inventoryStart;
  const operationalEnd=store.inventoryEnd;
  const logisticsChecks=[];
  transports.forEach((row,index)=>{
    const prefix=`Transporte ${index+1}`;
    addCheck(logisticsChecks,`${prefix}: informar data.`,hasValue(row.date));
    addCheck(logisticsChecks,`${prefix}: informar horário.`,hasValue(row.time));
    addCheck(logisticsChecks,`${prefix}: informar trajeto.`,hasValue(row.route));
    addCheck(logisticsChecks,`${prefix}: informar passageiros.`,hasValue(row.passengers));
    addCheck(logisticsChecks,`${prefix}: informar quantidade positiva.`,isPositive(row.quantity));
    if(hasValue(row.quantity)&&!isPositive(row.quantity))validationErrors.push(`${prefix}: a quantidade deve ser maior que zero.`);
    if(row.date&&operationalStart&&operationalEnd&&!dateIsBetween(row.date,operationalStart,operationalEnd))validationErrors.push(`${prefix}: a data deve estar dentro do período operacional (pré-contagem + inventário).`);
  });
  accommodations.forEach((row,index)=>{
    const prefix=`Hospedagem ${index+1}`;
    addCheck(logisticsChecks,`${prefix}: informar hóspedes.`,hasValue(row.guests));
    addCheck(logisticsChecks,`${prefix}: informar quartos.`,hasValue(row.rooms));
    addCheck(logisticsChecks,`${prefix}: informar entrada.`,hasValue(row.checkIn));
    addCheck(logisticsChecks,`${prefix}: informar saída.`,hasValue(row.checkOut));
    addCheck(logisticsChecks,`${prefix}: informar quantidade positiva de hóspedes.`,isPositive(row.count));
    if(row.checkIn&&row.checkOut&&row.checkIn>row.checkOut)validationErrors.push(`${prefix}: a entrada deve ser anterior ou igual à saída.`);
    if(hasValue(row.count)&&!isPositive(row.count))validationErrors.push(`${prefix}: a quantidade de hóspedes deve ser maior que zero.`);
  });
  if(logisticsApplicable&&!logisticsChecks.length)addCheck(logisticsChecks,'Orientações gerais de logística registradas.',hasValue(logistics.notes));
  blocks.push(makeBlock('logistics','Logística',logisticsChecks,logisticsApplicable));

  const equipmentChecks=[];
  let equipmentApplicable=false;
  ;[['clientEquipment','Equipamentos do cliente'],['contagemEquipment','Equipamentos Contagem']].forEach(([key,label])=>{
    const group=content[key]||{rows:[],notes:''};
    const rows=Array.isArray(group.rows)?group.rows:[];
    const groupApplicable=rows.length>0||hasValue(group.notes);
    equipmentApplicable=equipmentApplicable||groupApplicable;
    rows.forEach((row,index)=>{
      const prefix=`${label}, item ${index+1}`;
      addCheck(equipmentChecks,`${prefix}: informar equipamento.`,hasValue(row.equipment));
      addCheck(equipmentChecks,`${prefix}: informar dia.`,hasValue(row.date));
      addCheck(equipmentChecks,`${prefix}: informar turno.`,hasValue(row.shift));
      addCheck(equipmentChecks,`${prefix}: informar quantidade positiva.`,isPositive(row.quantity));
      addCheck(equipmentChecks,`${prefix}: informar status.`,hasValue(row.status));
      if(hasValue(row.quantity)&&!isPositive(row.quantity))validationErrors.push(`${prefix}: a quantidade deve ser maior que zero.`);
      if(row.date&&store.inventoryStart&&store.inventoryEnd&&!dateIsBetween(row.date,store.inventoryStart,store.inventoryEnd))validationErrors.push(`${prefix}: a data deve estar dentro do período do inventário.`);
    });
    if(groupApplicable&&!rows.length)addCheck(equipmentChecks,`${label}: detalhes gerais registrados.`,hasValue(group.notes));
  });
  blocks.push(makeBlock('equipment','Equipamentos',equipmentChecks,equipmentApplicable));

  const preCountChecks=[];
  if(store.preCountEnabled){
    addCheck(preCountChecks,'Informar o início da pré-contagem.',hasValue(store.preStart));
    addCheck(preCountChecks,'Informar o fim da pré-contagem.',hasValue(store.preEnd));
    addCheck(preCountChecks,'Manter o início da pré-contagem anterior ou igual ao fim.',store.preStart&&store.preEnd&&store.preStart<=store.preEnd);
    const rows=content.preCount?.rows||[];
    addCheck(preCountChecks,'Cadastrar ao menos uma equipe de pré-contagem.',rows.length>0);
    rows.forEach((row,index)=>{
      const prefix=`Pré-contagem ${index+1}`;
      addCheck(preCountChecks,`${prefix}: informar data.`,hasValue(row.date));
      addCheck(preCountChecks,`${prefix}: informar horário.`,hasValue(row.time));
      addCheck(preCountChecks,`${prefix}: informar equipe.`,hasValue(row.team));
      addCheck(preCountChecks,`${prefix}: informar quantidade positiva de pessoas.`,isPositive(row.count));
      if(hasValue(row.count)&&!isPositive(row.count))validationErrors.push(`${prefix}: a quantidade de pessoas deve ser maior que zero.`);
      if(row.date&&store.preStart&&store.preEnd&&!dateIsBetween(row.date,store.preStart,store.preEnd))validationErrors.push(`${prefix}: a data deve estar dentro do período da pré-contagem.`);
    });
    if(store.preStart&&store.preEnd&&store.preStart>store.preEnd)validationErrors.push('A data inicial da pré-contagem deve ser anterior ou igual à data final.');
    if(store.preEnd&&store.inventoryStart&&store.preEnd>store.inventoryStart)validationErrors.push('A pré-contagem deve terminar até o início do inventário.');
  }
  blocks.push(makeBlock('preCount','Pré-contagem',preCountChecks,Boolean(store.preCountEnabled)));

  const dayChecks=[];
  const days=Array.isArray(content.days)?content.days:[];
  addCheck(dayChecks,'Cadastrar ao menos um dia de inventário.',days.length>0);
  const datedDays=days.filter(item=>hasValue(item.date));
  const duplicateDates=datedDays.map(item=>item.date).filter((date,index,list)=>list.indexOf(date)!==index);
  if(duplicateDates.length)validationErrors.push(`Há dias repetidos no planejamento: ${unique(duplicateDates).map(formatDate).join(', ')}.`);
  const orderedDates=datedDays.map(item=>item.date);
  if(orderedDates.some((date,index)=>index>0&&date<orderedDates[index-1]))validationErrors.push('Os dias do inventário devem estar em ordem cronológica.');
  days.forEach((item,dayIndex)=>{
    const prefix=`Dia ${dayIndex+1}`;
    addCheck(dayChecks,`${prefix}: informar data dentro do período do inventário.`,hasValue(item.date)&&dateIsBetween(item.date,store.inventoryStart,store.inventoryEnd));
    addCheck(dayChecks,`${prefix}: informar equipe prevista positiva.`,isPositive(item.headcount));
    addCheck(dayChecks,`${prefix}: cadastrar ao menos uma área ou turno.`,Array.isArray(item.areas)&&item.areas.length>0);
    if(hasValue(item.headcount)&&!isPositive(item.headcount))validationErrors.push(`${prefix}: a equipe prevista deve ser maior que zero.`);
    if(item.date&&store.inventoryStart&&store.inventoryEnd&&!dateIsBetween(item.date,store.inventoryStart,store.inventoryEnd))validationErrors.push(`${prefix}: a data deve estar dentro do período do inventário.`);
    ;(item.areas||[]).forEach((areaItem,areaIndex)=>{
      const areaPrefix=`${prefix}, área ${areaIndex+1}`;
      addCheck(dayChecks,`${areaPrefix}: informar nome.`,hasValue(areaItem.name));
      addCheck(dayChecks,`${areaPrefix}: informar turno.`,hasValue(areaItem.shift));
      addCheck(dayChecks,`${areaPrefix}: informar horário de início.`,hasValue(areaItem.startsAt));
      addCheck(dayChecks,`${areaPrefix}: informar equipe prevista positiva.`,isPositive(areaItem.headcount));
      if(hasValue(areaItem.headcount)&&!isPositive(areaItem.headcount))validationErrors.push(`${areaPrefix}: a equipe prevista deve ser maior que zero.`);
      ;(areaItem.roles||[]).forEach((role,index)=>{
        addCheck(dayChecks,`${areaPrefix}, função ${index+1}: informar função.`,hasValue(role.role));
        addCheck(dayChecks,`${areaPrefix}, função ${index+1}: informar quantidade positiva.`,isPositive(role.count));
        if(hasValue(role.count)&&!isPositive(role.count))validationErrors.push(`${areaPrefix}, função ${index+1}: a quantidade deve ser maior que zero.`);
      });
      ;(areaItem.activities||[]).forEach((activity,index)=>addCheck(dayChecks,`${areaPrefix}, atividade ${index+1}: informar atividade.`,hasValue(activity.name)));
    });
  });
  blocks.push(makeBlock('days','Dias e áreas',dayChecks));

  Object.entries(checklistLabels).forEach(([key,label])=>{
    const items=content.checklists?.[key]||[];
    const checks=[];
    addCheck(checks,`${label}: manter ao menos um item.`,items.length>0);
    items.forEach((item,index)=>{
      addCheck(checks,`${label}, item ${index+1}: preencher a descrição.`,hasValue(item.label));
      addCheck(checks,`${label}, item ${index+1}: concluir o item.`,hasValue(item.label)&&item.done);
    });
    blocks.push(makeBlock(`checklist-${key}`,`Checklist — ${label}`,checks));
  });

  const knownKeys=new Set(['store','responsibilities','logistics','client_equipment','contagem_equipment','pre_count','inventory_days','checklists']);const byKey=Object.fromEntries((blockDefinitions||[]).map(definition=>[definition.block_key,definition]));const enabled=key=>!(blockDefinitions||[]).length||Boolean(byKey[key]?.active);const effectiveBlocks=blocks.map(block=>{const isEnabled=block.key==='equipment'?(enabled('client_equipment')||enabled('contagem_equipment')):block.key==='preCount'?enabled('pre_count'):block.key==='days'?enabled('inventory_days'):block.key.startsWith('checklist-')?enabled('checklists'):enabled(block.key);return {...block,applicable:block.applicable&&isEnabled,issues:block.applicable&&isEnabled?block.issues:[]}});(blockDefinitions||[]).filter(definition=>definition.active&&!knownKeys.has(definition.block_key)).forEach(definition=>effectiveBlocks.push(makeBlock(definition.block_key,definition.label,definition.required_for_completion?[{label:`${definition.label}: concluir o bloco.`,ok:Boolean(content.completedBlocks?.[definition.block_key])}]:[],true)));
  const applicableBlocks=effectiveBlocks.filter(block=>block.applicable);
  const allChecks=applicableBlocks.flatMap(block=>block.checks);
  const completedChecks=allChecks.filter(check=>check.ok).length;
  let percentage=allChecks.length?Math.floor(completedChecks/allChecks.length*100):0;
  const pendingBlocks=applicableBlocks.filter(block=>block.issues.length>0);
  const approvalIssues=unique([...pendingBlocks.flatMap(block=>block.issues),...validationErrors]);
  if(approvalIssues.length&&percentage===100)percentage=99;
  return {percentage,blocks:effectiveBlocks,pendingBlocks,validationErrors:unique(validationErrors),approvalIssues,approvalReady:approvalIssues.length===0};
}

function formatDate(value){if(!value)return '';const [year,month,date]=value.split('-').map(Number);return new Date(year,month-1,date).toLocaleDateString('pt-BR')}
function formatDateTime(value){if(!value)return 'Não informado';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function formatWeekday(value){if(!value)return 'Data não informada';const [year,month,date]=value.split('-').map(Number);const weekday=new Date(year,month-1,date).toLocaleDateString('pt-BR',{weekday:'long'});return weekday.charAt(0).toUpperCase()+weekday.slice(1)}
function inclusiveDates(start,end){const [startYear,startMonth,startDay]=start.split('-').map(Number);const [endYear,endMonth,endDay]=end.split('-').map(Number);const current=new Date(startYear,startMonth-1,startDay);const limit=new Date(endYear,endMonth-1,endDay);const dates=[];while(current<=limit){const year=current.getFullYear();const month=String(current.getMonth()+1).padStart(2,'0');const date=String(current.getDate()).padStart(2,'0');dates.push(`${year}-${month}-${date}`);current.setDate(current.getDate()+1)}return dates}
function confirmFilledRemoval(item,label,isFilled=hasRowData){return !isFilled(item)||window.confirm(`Excluir ${label}? Os dados preenchidos nesta seção serão perdidos.`)}

export default function PlanningEditor({projects,initialProjectId='',user,edit,canDimension=false,canApproveTi=false,canApprove=false,canEditPlanning=false,canManageTasks=false,canManageLifecycle=false,catalogs={},fields=[],onSaveProjectCore,onLifecycle,onUpdateTask,onSyncTasks,onDirtyChange,onSaved}){
  const [selected,setSelected]=useState('');
  const [content,setContent]=useState(initial());
  const [savedSnapshot,setSavedSnapshot]=useState('');
  const [saving,setSaving]=useState(false);
  const [notice,setNotice]=useState('');
  const [tiDraft,setTiDraft]=useState({system_name:'',ti_contact_name:'',ti_contact_email:'',ti_contact_phone:'',notes:''});
  const [tiSavedSnapshot,setTiSavedSnapshot]=useState('');
  const [selectedVisitId,setSelectedVisitId]=useState('');
  const [tiSaving,setTiSaving]=useState(false);
  const [dimensionDraft,setDimensionDraft]=useState({options:[],selected_option_id:'',visit_starts:['',''],notes:''});
  const [dimensionSavedSnapshot,setDimensionSavedSnapshot]=useState('');
  const [dimensionSaving,setDimensionSaving]=useState(false);
  const modalRef=useRef(null);
  const closeButtonRef=useRef(null);
  const openerRef=useRef(null);
  const dirtyRef=useRef(false);
  const project=projects.find(item=>item.id===selected);
  const approvalStageReady=Boolean(project&&['planning','awaiting_dates'].includes(project.status));
  const planningAvailable=Boolean(project&&['planning','awaiting_dates','confirmed'].includes(project.status));
  const isReadOnly=project?.status==='confirmed'||(planningAvailable&&!canEditPlanning);
  const audit=useMemo(()=>auditPlanning(content,catalogs.blocks||[]),[content,catalogs.blocks]);
  const currentSnapshot=useMemo(()=>JSON.stringify(content),[content]);
  const planningDirty=Boolean(project&&savedSnapshot&&currentSnapshot!==savedSnapshot);
  const tiCurrentSnapshot=useMemo(()=>JSON.stringify({draft:tiDraft,selectedVisitId}),[tiDraft,selectedVisitId]);
  const tiDirty=Boolean(project&&tiSavedSnapshot&&tiCurrentSnapshot!==tiSavedSnapshot);
  const dimensionCurrentSnapshot=useMemo(()=>JSON.stringify(dimensionDraft),[dimensionDraft]);
  const dimensionDirty=Boolean(project&&dimensionSavedSnapshot&&dimensionCurrentSnapshot!==dimensionSavedSnapshot);
  const isDirty=project?.status==='awaiting_dimensioning'?dimensionDirty:project?.status==='awaiting_ti'?tiDirty:planningDirty;
  dirtyRef.current=isDirty;
  const selectProject=(id,trigger)=>{if(id===selected)return true;if(isDirty&&!window.confirm('Existem alterações não salvas. Deseja trocar de operação e descartá-las?'))return false;if(trigger)openerRef.current=trigger.matches?.('button,a,input,select,textarea,[tabindex]')?trigger:trigger.querySelector?.('button')||null;setSelected(id);return true};
  const closeModal=()=>{if(isDirty&&!window.confirm('Existem alterações não salvas. Deseja fechar e descartá-las?'))return false;setSelected('');requestAnimationFrame(()=>openerRef.current?.focus?.());return true};
  const scrollToAuditBlock=key=>{const target=document.getElementById(key==='equipment'?'clientEquipment':key);if(!target)return;target.scrollIntoView({behavior:'smooth',block:'start'});window.setTimeout(()=>target.querySelector('input,textarea,select,button')?.focus({preventScroll:true}),300)};
  const auditKey=key=>['clientEquipment','contagemEquipment'].includes(key)?'equipment':key;
  const blockAudit=key=>key==='checklists'?audit.blocks.filter(block=>block.key.startsWith('checklist-')).flatMap(block=>block.issues):audit.blocks.find(block=>block.key===auditKey(key))?.issues||[];
  const blockDefinition=key=>(catalogs.blocks||[]).find(block=>block.block_key===key);const blockActive=key=>!(catalogs.blocks||[]).length||blockDefinition(key)?.active!==false;const blockTitle=(key,fallback)=>blockDefinition(key)?.label||fallback;
  const isBlockDone=key=>Boolean(content.completedBlocks?.[key])&&blockAudit(key).length===0;
  const toggleBlock=key=>{if(isReadOnly)return;const done=isBlockDone(key);if(!done){const issues=blockAudit(key);if(issues.length){setNotice(`Resolva ${issues.length} pendência(s) antes de concluir este bloco.`);return}}set(['completedBlocks',key],!done)};
  const reopenChangedBlock=(next,key)=>{const blockKey=['clientEquipment','contagemEquipment'].includes(key)?key:key==='checklists'?'checklists':key;if(next.completedBlocks?.[blockKey])next.completedBlocks[blockKey]=false};

  useEffect(()=>{if(!project){setContent(initial());setSavedSnapshot('');return}const saved=project.planning?.content;const next=merge(saved);if(!saved&&Array.isArray(catalogs.checklists)){const templateFor=type=>{const normalizedType=String(project.inventory_type||'').trim().toLocaleLowerCase('pt-BR');const matches=catalogs.checklists.filter(template=>template.checklist_type===type&&(!template.inventory_type||String(template.inventory_type).trim().toLocaleLowerCase('pt-BR')===normalizedType)).sort((a,b)=>(b.inventory_type?1:0)-(a.inventory_type?1:0));return matches[0]?.checklist_template_items?.slice().sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(item=>({id:uid(),label:item.label,done:false,required:item.required!==false}))||null};const pre=templateFor('pre_inventory_visit');const planning=templateFor('planning');const final=templateFor('final');if(pre?.length)next.checklists.preInventory=pre;if(planning?.length)next.checklists.planning=planning;if(final?.length)next.checklists.final=final}setContent(next);setSavedSnapshot(JSON.stringify(next));setNotice('')},[project?.id,project?.planning?.updated_at,project?.planning?.version]);
  useEffect(()=>{if(!project){const empty={system_name:'',ti_contact_name:'',ti_contact_email:'',ti_contact_phone:'',notes:''};setTiDraft(empty);setSelectedVisitId('');setTiSavedSnapshot('');return}const source=project.ti_validation||{};const next={system_name:source.system_name||project.layout_system||'',ti_contact_name:source.ti_contact_name||project.ti_contact_name||'',ti_contact_email:source.ti_contact_email||project.ti_contact_email||'',ti_contact_phone:source.ti_contact_phone||project.ti_contact_phone||'',notes:source.notes||''};const selectedId=project.selected_date_option_id||(project.date_option_records||[]).find(option=>option.status==='selected')?.id||'';setTiDraft(next);setSelectedVisitId(selectedId);setTiSavedSnapshot(JSON.stringify({draft:next,selectedVisitId:selectedId}))},[project?.id,project?.ti_validation?.status,project?.ti_validation?.validated_at,project?.updated_at,project?.selected_date_option_id]);
  useEffect(()=>{if(!project){const empty={options:[],selected_option_id:'',visit_starts:['',''],notes:''};setDimensionDraft(empty);setDimensionSavedSnapshot('');return}const stored=(project.dimensioning_options||[]).map(option=>({id:option.id,title:option.title||'',days:option.days??'',team_size:option.team_size??'',notes:option.details?.notes||''}));const options=stored.length?stored:[dimensionOption('Opção 1'),dimensionOption('Opção 2')];const selectedOption=(project.dimensioning_options||[]).find(option=>option.approved)?.id||'';const visits=[0,1].map(index=>toLocalDateTime(project.date_option_records?.[index]?.starts_at));const next={options,selected_option_id:selectedOption,visit_starts:visits,notes:project.dimensioning?.notes||''};setDimensionDraft(next);setDimensionSavedSnapshot(JSON.stringify(next))},[project?.id,project?.dimensioning?.status,project?.dimensioning?.updated_at,project?.updated_at]);
  useEffect(()=>{if(initialProjectId&&initialProjectId!==selected&&projects.some(item=>item.id===initialProjectId)){if(isDirty&&!window.confirm('Existem alterações não salvas. Deseja abrir outra operação e descartá-las?'))return;setSelected(initialProjectId)}},[initialProjectId]);
  useEffect(()=>{if(!isDirty)return;const warn=event=>{event.preventDefault();event.returnValue=''};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[isDirty]);
  useEffect(()=>{onDirtyChange?.(isDirty)},[isDirty,onDirtyChange]);
  useEffect(()=>{if(!project)return;const previousOverflow=document.body.style.overflow;const app=document.querySelector('.app');document.body.style.overflow='hidden';if(app){app.inert=true;app.setAttribute('aria-hidden','true')}const onKeyDown=event=>{if(event.key==='Escape'){event.preventDefault();if(dirtyRef.current&&!window.confirm('Existem alterações não salvas. Deseja fechar e descartá-las?'))return;setSelected('');requestAnimationFrame(()=>openerRef.current?.focus?.());return}if(event.key!=='Tab'||!modalRef.current)return;const focusable=[...modalRef.current.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex]:not([tabindex="-1"])')].filter(element=>!element.hasAttribute('hidden'));if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};window.addEventListener('keydown',onKeyDown);requestAnimationFrame(()=>closeButtonRef.current?.focus());return()=>{document.body.style.overflow=previousOverflow;if(app){app.inert=false;app.removeAttribute('aria-hidden')}window.removeEventListener('keydown',onKeyDown)}},[project?.id]);
  useEffect(()=>()=>onDirtyChange?.(false),[onDirtyChange]);

  const set=(path,value)=>setContent(current=>{const next=structuredClone(current);let target=next;path.slice(0,-1).forEach(key=>target=target[key]);target[path.at(-1)]=value;reopenChangedBlock(next,path[0]);return next});
  const add=(path,item)=>setContent(current=>{const next=structuredClone(current);let target=next;path.forEach(key=>target=target[key]);target.push(item);reopenChangedBlock(next,path[0]);return next});
  const remove=(path,index)=>setContent(current=>{const next=structuredClone(current);let target=next;path.forEach(key=>target=target[key]);target.splice(index,1);reopenChangedBlock(next,path[0]);return next});
  const row=(path,index,key,value)=>setContent(current=>{const next=structuredClone(current);let target=next;path.forEach(pathKey=>target=target[pathKey]);target[index][key]=value;reopenChangedBlock(next,path[0]);return next});

  function generateDays(){
    const {inventoryStart,inventoryEnd}=content.store;
    if(!inventoryStart||!inventoryEnd){setNotice('Informe o início e o fim do inventário antes de gerar os dias.');return}
    if(inventoryStart>inventoryEnd){setNotice('Corrija a ordem das datas do inventário antes de gerar os dias.');return}
    const startDate=new Date(`${inventoryStart}T12:00:00`);
    const endDate=new Date(`${inventoryEnd}T12:00:00`);
    const totalDays=Math.floor((endDate-startDate)/86400000)+1;
    if(!Number.isFinite(totalDays)||totalDays<1){setNotice('O período informado é inválido. Revise as datas.');return}
    if(totalDays>60){setNotice('O período não pode gerar mais de 60 dias de inventário. Revise as datas.');return}
    const dates=inclusiveDates(inventoryStart,inventoryEnd);
    setContent(current=>{
      const existing=Array.isArray(current.days)?current.days:[];
      const consumed=new Set();
      const generated=dates.map(dateValue=>{
        const match=existing.find(item=>item.date===dateValue&&!consumed.has(item));
        if(match){consumed.add(match);return match}
        return day(dateValue);
      });
      return {...current,days:[...generated,...existing.filter(item=>!consumed.has(item))]};
    });
    setNotice(`${dates.length} dia(s) do período foram gerados ou mesclados sem apagar dados existentes.`);
  }

  async function saveDimensioning(complete=false){
    if(!project||project.status!=='awaiting_dimensioning')return;
    if(!canDimension){setNotice('A edição do dimensionamento é restrita à operação e aos gestores autorizados.');return}
    const options=dimensionDraft.options.map(option=>({...option,title:option.title.trim()}));
    const invalid=options.filter(option=>!option.title||(complete&&(!isPositive(option.days)||!isPositive(option.team_size))));
    const visits=dimensionDraft.visit_starts.filter(Boolean).map(toIsoDateTime);
    if(!options.length){setNotice('Cadastre ao menos uma opção de dimensionamento.');return}
    if(invalid.length){setNotice(complete?'Preencha título, quantidade de dias e tamanho positivo de equipe em todas as opções.':'Toda opção precisa de um título antes de salvar.');return}
    if(complete&&options.length<2){setNotice('Cadastre ao menos duas opções completas para a escolha do dimensionamento.');return}
    if(complete&&!dimensionDraft.selected_option_id){setNotice('Selecione a opção de dimensionamento aprovada.');return}
    if(complete&&visits.length<2){setNotice('Informe duas opções de data e horário para a visita de dimensionamento.');return}
    if(complete&&!window.confirm('Concluir o dimensionamento com a opção aprovada e encaminhar a operação para TI?'))return;
    setDimensionSaving(true);
    try{
      const payload={...dimensionDraft,options,visit_starts:visits};
      await edit?.(project.id,{dimensioning_draft:payload,complete_dimensioning:complete},complete?'Dimensionamento concluído e encaminhado para TI.':'Rascunho do dimensionamento salvo.');
      setDimensionSavedSnapshot(JSON.stringify({...payload,visit_starts:dimensionDraft.visit_starts}));
      setNotice(complete?'Dimensionamento concluído e encaminhado para TI.':'Rascunho do dimensionamento salvo.');
    }catch(error){setNotice(error.message||String(error))}finally{setDimensionSaving(false)}
  }

  async function saveTi(approve=false){
    if(!project||project.status!=='awaiting_ti')return;
    if(!canApproveTi){setNotice('A validação de TI é restrita ao perfil de TI e aos gestores autorizados.');return}
    const missing=[];
    if(!tiDraft.system_name.trim())missing.push('sistema ou layout');
    if(!tiDraft.ti_contact_name.trim())missing.push('nome do contato de TI');
    if(!tiDraft.ti_contact_email.trim())missing.push('e-mail do contato de TI');
    if(tiDraft.ti_contact_email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(tiDraft.ti_contact_email))missing.push('e-mail válido do contato de TI');
    const visitOptions=project.date_option_records||[];
    if(approve&&!visitOptions.length)missing.push('ao menos uma opção de visita registrada no dimensionamento');
    if(approve&&visitOptions.length&&!selectedVisitId)missing.push('uma opção de visita selecionada');
    if(missing.length){setNotice(`Revise antes de ${approve?'aprovar':'salvar'}: ${missing.join(', ')}.`);return}
    if(approve&&!window.confirm('Validar TI, confirmar a visita selecionada e liberar o planejamento?'))return;
    setTiSaving(true);
    try{
      await edit?.(project.id,{ti_validation:tiDraft,selected_date_option_id:selectedVisitId||null,...(approve?{status:'planning'}:{})},approve?'TI validada; planejamento liberado.':'Rascunho da validação de TI salvo.');
      setTiSavedSnapshot(JSON.stringify({draft:tiDraft,selectedVisitId}));
      setNotice(approve?'TI validada e planejamento liberado.':'Rascunho de TI salvo com sucesso.');
    }catch(error){setNotice(error.message||String(error))}finally{setTiSaving(false)}
  }

  async function save(approve=false){
    if(!project)return;
    if(!planningAvailable||isReadOnly){setNotice('Este planejamento está disponível somente para consulta nesta etapa.');return}
    if(approve&&!canApprove){setNotice('A aprovação é restrita a administradores, supervisores e gestores operacionais.');return}
    if(approve&&!approvalStageReady){setNotice('Este projeto ainda não está em uma etapa elegível para aprovação.');return}
    if(approve&&!audit.approvalReady){
      const preview=audit.approvalIssues.slice(0,3).join(' ');
      const remaining=audit.approvalIssues.length-3;
      setNotice(`Não foi possível aprovar. ${preview}${remaining>0?` E mais ${remaining} pendência(s).`:''}`);
      return;
    }
    setSaving(true);
    try{
      if(!supabase){
        await edit?.(project.id,{planning_update:{content,completion_percentage:audit.percentage,status:approve?'approved':'in_progress'},sync_task_inventory_start:content.store?.inventoryStart||null,...(approve?{status:'confirmed'}:{})},approve?'Planejamento aprovado no modo demonstração.':'Rascunho salvo no modo demonstração.');
      }else if(approve){
        const {error}=await supabase.rpc('approve_planning',{p_project_id:project.id,p_content:content,p_completion_percentage:audit.percentage});
        if(error)throw error;
      }else{
        const payload={project_id:project.id,content,completion_percentage:audit.percentage,status:'in_progress',updated_at:new Date().toISOString()};
        const startedBy=project.planning?.started_by||user?.id;
        if(startedBy)payload.started_by=startedBy;
        const {error}=await supabase.from('plannings').upsert(payload,{onConflict:'project_id'});
        if(error)throw error;
      }
      if(supabase&&canManageTasks)await onSyncTasks?.(project.id,content.store?.inventoryStart||null);
      if(approve)setNotice('Planejamento aprovado de forma segura e transacional.');
      else if(audit.validationErrors.length)setNotice(`Rascunho salvo com aviso: ${audit.validationErrors.length} inconsistência(s) de datas ou quantidades e ${audit.approvalIssues.length} pendência(s) no total.`);
      else if(audit.approvalIssues.length)setNotice(`Rascunho salvo com ${audit.approvalIssues.length} pendência(s).`);
      else setNotice('Rascunho salvo e pronto para aprovação.');
      setSavedSnapshot(JSON.stringify(content));
      if(supabase)await onSaved?.();
    }catch(error){setNotice(error.message)}finally{setSaving(false)}
  }

  const exportRows=()=>{const rows=[['PLANEJAMENTO DE INVENTÁRIO'],['Cliente',project.company_name||''],['Referência',project.reference||''],['Status',project.status||''],['Progresso',`${audit.percentage}%`],['Unidade',content.store?.unit||''],['Período do inventário',`${content.store?.inventoryStart||''} a ${content.store?.inventoryEnd||''}`],['Efetivo geral',content.store?.headcount||'']];const push=(title,headers,items,mapper)=>{rows.push([], [title], headers);(items||[]).forEach(item=>rows.push(mapper(item)))};push('Responsáveis',['Função','Responsável','Observação'],content.responsibilities,item=>[item.role||'',item.person||'',item.notes||'']);push('Transportes',['Data','Horário','Trajeto','Passageiros','Quantidade','Observação'],content.logistics?.transports,item=>[item.date||'',item.time||'',item.route||'',item.passengers||'',item.quantity||'',item.notes||'']);push('Hospedagens',['Hóspedes','Quartos','Entrada','Saída','Quantidade','Observação'],content.logistics?.accommodations,item=>[item.guests||'',item.rooms||'',item.checkIn||'',item.checkOut||'',item.count||'',item.notes||'']);push('Equipamentos do cliente',['Equipamento','Data','Turno','Quantidade','Status','Observação'],content.clientEquipment?.rows,item=>[item.equipment||'',item.date||'',item.shift||'',item.quantity||'',item.status||'',item.notes||'']);push('Equipamentos Contagem',['Equipamento','Data','Turno','Quantidade','Status','Observação'],content.contagemEquipment?.rows,item=>[item.equipment||'',item.date||'',item.shift||'',item.quantity||'',item.status||'',item.notes||'']);push('Pré-contagem',['Data','Horário','Equipe','Quantidade','Observação'],content.preCount?.rows,item=>[item.date||'',item.time||'',item.team||'',item.count||'',item.notes||'']);rows.push([],['Dias e áreas'],['Dia','Área','Turno','Início','Equipe','Função','Qtd. função','Nomes','Atividade','Observação']);(content.days||[]).forEach((dayItem,index)=>(dayItem.areas||[]).forEach(areaItem=>{const roles=areaItem.roles?.length?areaItem.roles:[{}];const activities=areaItem.activities?.length?areaItem.activities:[{}];const total=Math.max(roles.length,activities.length);for(let i=0;i<total;i+=1){const role=roles[i]||{},activity=activities[i]||{};rows.push([dayItem.date||`Dia ${index+1}`,areaItem.name||'',areaItem.shift||'',areaItem.startsAt||'',areaItem.headcount||'',role.role||'',role.count||'',role.names||'',activity.name||'',activity.notes||''])}}));Object.entries(content.checklists||{}).forEach(([key,items])=>push(`Checklist ${key}`,['Item','Concluído','Concluído em'],items,item=>[item.label||'',item.done?'Sim':'Não',item.completedAt||'']));return rows};
  const exportFilename=()=>`planejamento-${(project.company_name||'inventario').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'inventario'}`;
  function exportExcel(){const sheet=XLSX.utils.aoa_to_sheet(exportRows());sheet['!cols']=[{wch:28},{wch:28},{wch:24},{wch:18},{wch:18},{wch:24},{wch:18},{wch:24},{wch:32},{wch:32}];const workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,sheet,'Planejamento');XLSX.writeFile(workbook,`${exportFilename()}.xlsx`);setNotice('Excel exportado com sucesso.')}
  function exportPdf(){const doc=new jsPDF({unit:'pt',format:'a4'});const rows=exportRows();let y=42;rows.forEach((row,index)=>{const text=row.filter(value=>value!==null&&value!==undefined&&String(value)!=='').join('  |  ');if(!text){y+=8;return}const lines=doc.splitTextToSize(text,515);if(y+lines.length*13>800){doc.addPage();y=42}doc.setFont('helvetica',index===0?'bold':'normal');doc.setFontSize(index===0?15:9);doc.setTextColor(index===0?'#242323':'#4f5661');doc.text(lines,40,y);y+=lines.length*13+4});doc.save(`${exportFilename()}.pdf`);setNotice('PDF exportado com sucesso.')}
  return <section className="planning-shell">
    <PlanningKanban projects={projects} stages={catalogs.stages||[]} selectedId={selected} onSelect={selectProject} edit={edit} canDimension={canDimension} canApproveTi={canApproveTi}/>
    {project&&createPortal(<div className="planning-modal-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)closeModal()}}><section ref={modalRef} className="planning-modal" role="dialog" aria-modal="true" aria-labelledby="planning-modal-title" aria-describedby="planning-modal-description"><header className="planning-modal-top"><div><span className={`kanban-status kanban-status-${project.status}`}>{planningStatus[project.status]||project.status}</span><h2 id="planning-modal-title">{project.company_name}</h2><p id="planning-modal-description">{project.reference} · Abra, revise e conclua somente a etapa atual desta operação.</p></div><button ref={closeButtonRef} type="button" className="planning-modal-close" aria-label="Fechar operação" onClick={closeModal}>×</button></header><div className="planning-modal-scroll">
    <div className="card planning-header" id="planning-editor">
      <div><h2>{project.status==='awaiting_dimensioning'?'Dimensionamento e opções':project.status==='awaiting_ti'?'Validação de TI e visita':'Planejamento por blocos'}</h2><p>{project.status==='awaiting_dimensioning'?'Compare cenários, escolha a opção aprovada e registre duas alternativas para a visita.':project.status==='awaiting_ti'?'Revise os dados técnicos, confirme uma das opções de visita e só então libere o planejamento.':'Preencha no seu ritmo. O progresso fica salvo e a aprovação exige todos os blocos aplicáveis e os três checklists concluídos.'}</p></div>
      <div className="planning-tools"><select value={selected} onChange={event=>selectProject(event.target.value)}><option value="">Selecione uma solicitação</option>{projects.map(item=><option key={item.id} value={item.id}>{item.company_name} · {item.reference}</option>)}</select>{project&&<><span className={`save-state ${isReadOnly?'is-locked':isDirty?'is-dirty':'is-saved'}`}>{isReadOnly?'Somente consulta':isDirty?'Alterações não salvas':'Tudo salvo'}</span>{planningAvailable&&<div className="export-actions"><button type="button" onClick={exportPdf}>Exportar PDF</button><button type="button" onClick={exportExcel}>Exportar Excel</button></div>}</>}</div>
    </div>
    {canManageLifecycle&&<><ProjectCoreAdmin project={project} fields={fields} inventoryTypes={catalogs.inventoryTypes||[]} onSave={onSaveProjectCore}/><LifecycleControls project={project} stages={catalogs.stages||[]} onAction={onLifecycle}/></>}
    <ProjectTasksPanel project={project} canManage={canManageTasks} onUpdateTask={onUpdateTask} onSyncTasks={onSyncTasks}/>
    {project.status==='awaiting_dimensioning'?<DimensioningPanel project={project} draft={dimensionDraft} setDraft={setDimensionDraft} dirty={dimensionDirty} saving={dimensionSaving} canDimension={canDimension} notice={notice} onSave={()=>saveDimensioning(false)} onComplete={()=>saveDimensioning(true)}/>:project.status==='awaiting_ti'?<TiValidationPanel project={project} draft={tiDraft} setDraft={setTiDraft} selectedVisitId={selectedVisitId} setSelectedVisitId={setSelectedVisitId} dirty={tiDirty} saving={tiSaving} canApproveTi={canApproveTi} notice={notice} onSave={()=>saveTi(false)} onApprove={()=>saveTi(true)}/>:!planningAvailable?<div className="card stage-gate-card"><span className={`kanban-status kanban-status-${project.status}`}>{planningStatus[project.status]||project.status}</span><h2>Esta operação ainda não chegou ao preenchimento do planejamento</h2><p>Use as ações do cartão no Kanban para concluir o gate atual. Os blocos serão liberados após a validação necessária.</p><button type="button" onClick={closeModal}>Voltar ao Kanban</button></div>:<>
      <DimensioningSummary project={project}/>{project.ti_validation&&<TiApprovalHistory project={project}/>}<div className={`card progress-card ${isReadOnly?'is-readonly':''}`}>
        <div className="progress-heading"><div><b>{project.company_name}</b><small>{project.reference} · {planningStatus[project.status]||project.status}</small></div><div className="progress-status"><span className={`save-state ${isReadOnly?'is-locked':isDirty?'is-dirty':'is-saved'}`}>{isReadOnly?'Planejamento bloqueado':isDirty?'Alterações não salvas':'Rascunho salvo'}</span><b>{audit.percentage}% concluído</b></div></div>{isReadOnly&&<div className="readonly-banner"><b>{project.status==='confirmed'?'Planejamento concluído':'Modo somente consulta'}</b><span>{project.status==='confirmed'?'Alterações exigem reabertura controlada e histórico.':'Seu perfil pode consultar, mas não editar este planejamento.'}</span></div>}
        <div className="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow={audit.percentage}><i style={{width:`${audit.percentage}%`}}/></div>
        <AuditSummary audit={audit} onNavigate={scrollToAuditBlock}/>
      </div>
      <Block active={blockActive('store')} readOnly={isReadOnly} blockKey="store" completed={isBlockDone('store')} onToggle={()=>toggleBlock('store')} title={`1. ${blockTitle('store','Informações da loja')}`} subtitle="Períodos e efetivo geral">
        <div className="grid"><Input label="Unidade" value={content.store.unit} onChange={value=>set(['store','unit'],value)}/><Input label="Efetivo geral previsto" type="number" value={content.store.headcount} onChange={value=>set(['store','headcount'],value)}/><Toggle label="Possui pré-contagem" checked={content.store.preCountEnabled} onChange={value=>set(['store','preCountEnabled'],value)}/>{content.store.preCountEnabled&&<><Input label="Início pré-contagem" type="date" value={content.store.preStart} onChange={value=>set(['store','preStart'],value)}/><Input label="Fim pré-contagem" type="date" value={content.store.preEnd} onChange={value=>set(['store','preEnd'],value)}/></>}<Input label="Início do inventário" type="date" value={content.store.inventoryStart} onChange={value=>set(['store','inventoryStart'],value)}/><Input label="Fim do inventário" type="date" value={content.store.inventoryEnd} onChange={value=>set(['store','inventoryEnd'],value)}/></div>
      </Block>
      <Block active={blockActive('responsibilities')} readOnly={isReadOnly} blockKey="responsibilities" completed={isBlockDone('responsibilities')} onToggle={()=>toggleBlock('responsibilities')} title={`2. ${blockTitle('responsibilities','Responsáveis pela operação')}`}  subtitle="Funções configuráveis e responsáveis">
        <Rows rows={content.responsibilities} add={()=>add(['responsibilities'],{id:uid(),role:'',person:'',notes:''})} remove={index=>remove(['responsibilities'],index)}>{(item,index)=><div className="row-grid"><Input label="Função" list="roles" value={item.role} onChange={value=>row(['responsibilities'],index,'role',value)}/><Input label="Responsável" value={item.person} onChange={value=>row(['responsibilities'],index,'person',value)}/><Input label="Observação" value={item.notes} onChange={value=>row(['responsibilities'],index,'notes',value)}/></div>}</Rows>
      </Block>
      <Block active={blockActive('logistics')} readOnly={isReadOnly} blockKey="logistics" completed={isBlockDone('logistics')} onToggle={()=>toggleBlock('logistics')} title={`3. ${blockTitle('logistics','Logística')}`}  subtitle="Transporte, hospedagem e orientações">
        <h3>Transporte</h3>
        <Rows rows={content.logistics.transports} add={()=>add(['logistics','transports'],{id:uid(),date:'',time:'',route:'',passengers:'',quantity:'',notes:''})} remove={index=>remove(['logistics','transports'],index)}>{(item,index)=><div className="row-grid four"><Input label="Data" type="date" value={item.date} onChange={value=>row(['logistics','transports'],index,'date',value)}/><Input label="Horário" type="time" value={item.time} onChange={value=>row(['logistics','transports'],index,'time',value)}/><Input label="Trajeto" value={item.route} onChange={value=>row(['logistics','transports'],index,'route',value)}/><Input label="Passageiros" value={item.passengers} onChange={value=>row(['logistics','transports'],index,'passengers',value)}/><Input label="Qtd." type="number" value={item.quantity} onChange={value=>row(['logistics','transports'],index,'quantity',value)}/><Input label="Observação" value={item.notes} onChange={value=>row(['logistics','transports'],index,'notes',value)}/></div>}</Rows>
        <h3>Hospedagem</h3>
        <Rows rows={content.logistics.accommodations} add={()=>add(['logistics','accommodations'],{id:uid(),guests:'',rooms:'',checkIn:'',checkOut:'',count:'',notes:''})} remove={index=>remove(['logistics','accommodations'],index)}>{(item,index)=><div className="row-grid four"><Input label="Hóspedes" value={item.guests} onChange={value=>row(['logistics','accommodations'],index,'guests',value)}/><Input label="Quartos" value={item.rooms} onChange={value=>row(['logistics','accommodations'],index,'rooms',value)}/><Input label="Entrada" type="date" value={item.checkIn} onChange={value=>row(['logistics','accommodations'],index,'checkIn',value)}/><Input label="Saída" type="date" value={item.checkOut} onChange={value=>row(['logistics','accommodations'],index,'checkOut',value)}/><Input label="Qtd. hóspedes" type="number" value={item.count} onChange={value=>row(['logistics','accommodations'],index,'count',value)}/><Input label="Observação" value={item.notes} onChange={value=>row(['logistics','accommodations'],index,'notes',value)}/></div>}</Rows>
        <Text label="Observações gerais de logística" value={content.logistics.notes} onChange={value=>set(['logistics','notes'],value)}/>
      </Block>
      <Equipment active={blockActive('client_equipment')} readOnly={isReadOnly} blockKey="clientEquipment" completed={isBlockDone('clientEquipment')} onToggle={()=>toggleBlock('clientEquipment')} title={`4. ${blockTitle('client_equipment','Equipamentos do cliente')}`}  value={content.clientEquipment} path="clientEquipment" setContent={setContent}/>
      <Equipment active={blockActive('contagem_equipment')} readOnly={isReadOnly} blockKey="contagemEquipment" completed={isBlockDone('contagemEquipment')} onToggle={()=>toggleBlock('contagemEquipment')} title={`5. ${blockTitle('contagem_equipment','Equipamentos Contagem')}`}  value={content.contagemEquipment} path="contagemEquipment" setContent={setContent}/>
      <Block active={blockActive('pre_count')} readOnly={isReadOnly} blockKey="preCount" completed={isBlockDone('preCount')} onToggle={()=>toggleBlock('preCount')} title={`6. ${blockTitle('pre_count','Pré-contagem')}`}  subtitle="Datas, horários, equipe e efetivo">
        {!content.store.preCountEnabled&&<p className="block-hint">Ative “Possui pré-contagem” nas informações da loja para tornar este bloco obrigatório.</p>}
        <Rows rows={content.preCount.rows} add={()=>add(['preCount','rows'],{id:uid(),date:'',time:'',team:'',count:'',notes:''})} remove={index=>remove(['preCount','rows'],index)}>{(item,index)=><div className="row-grid four"><Input label="Data" type="date" value={item.date} onChange={value=>row(['preCount','rows'],index,'date',value)}/><Input label="Horário" type="time" value={item.time} onChange={value=>row(['preCount','rows'],index,'time',value)}/><Input label="Equipe" value={item.team} onChange={value=>row(['preCount','rows'],index,'team',value)}/><Input label="Qtd. pessoas" type="number" value={item.count} onChange={value=>row(['preCount','rows'],index,'count',value)}/><Input label="Observação" value={item.notes} onChange={value=>row(['preCount','rows'],index,'notes',value)}/></div>}</Rows>
        <Text label="Detalhes da pré-contagem" value={content.preCount.notes} onChange={value=>set(['preCount','notes'],value)}/>
      </Block>
      <Block active={blockActive('inventory_days')} readOnly={isReadOnly} blockKey="days" completed={isBlockDone('days')} onToggle={()=>toggleBlock('days')} title={`7. ${blockTitle('inventory_days','Dias, turnos e áreas do inventário')}`}  subtitle="Adicione quantos dias e sub-blocos forem necessários">
        <div className="day-actions"><button onClick={()=>add(['days'],day())}>+ Adicionar dia</button><button onClick={generateDays}>Gerar dias do período</button></div>
        {content.days.map((item,index)=><DayEditor key={item.id||index} day={item} index={index} setContent={setContent} removeDay={()=>remove(['days'],index)}/>) }
      </Block>
      <Block active={blockActive('checklists')} readOnly={isReadOnly} blockKey="checklists" completed={isBlockDone('checklists')} onToggle={()=>toggleBlock('checklists')} title={`8. ${blockTitle('checklists','Checklists')}`}  subtitle="Edite os itens conforme a lista final da Contagem; os três checklists precisam estar preenchidos e concluídos para aprovação.">
        <Checklist anchorId="checklist-preInventory" title="Checklist Visita Pré-Inventário" deadline={content.store.inventoryStart} subtitle="Realizar até um dia antes do inventário; recomendado com três dias de antecedência." items={content.checklists.preInventory} userId={user?.id} onChange={items=>set(['checklists','preInventory'],items)}/>
        <Checklist anchorId="checklist-planning" title="Checklist de planejamento" subtitle="Itens operacionais que serão definidos e refinados pela Contagem." items={content.checklists.planning} userId={user?.id} onChange={items=>set(['checklists','planning'],items)}/>
        <Checklist anchorId="checklist-final" title="Checklist final de aprovação" subtitle="Obrigatório para concluir e aprovar o planejamento." items={content.checklists.final} userId={user?.id} onChange={items=>set(['checklists','final'],items)}/>
      </Block>
      {(catalogs.blocks||[]).filter(definition=>definition.active&&!['store','responsibilities','logistics','client_equipment','contagem_equipment','pre_count','inventory_days','checklists'].includes(definition.block_key)).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(definition=><Block key={definition.id} readOnly={isReadOnly} blockKey={definition.block_key} completed={isBlockDone(definition.block_key)} onToggle={()=>toggleBlock(definition.block_key)} title={definition.label} subtitle={definition.description||'Bloco configurável'}><Text label="Orientações e observações" value={content.dynamicBlocks?.[definition.block_key]?.notes||''} onChange={value=>setContent(current=>({...current,dynamicBlocks:{...(current.dynamicBlocks||{}),[definition.block_key]:{...(current.dynamicBlocks?.[definition.block_key]||{}),notes:value}}}))}/></Block>)}
      <div className={`sticky-actions ${isReadOnly?'is-readonly':''}`}><span>{isReadOnly?(project.status==='confirmed'?'Planejamento concluído e protegido contra edição.':'Seu perfil possui acesso somente para consulta.'):notice||(isDirty?'Há alterações não salvas.':!canApprove?'A aprovação é restrita a administradores, supervisores e gestores operacionais.':!approvalStageReady?'Este projeto ainda não está em uma etapa elegível para aprovação.':'Rascunho salvo.')}</span>{!isReadOnly&&<><button onClick={()=>save(false)} disabled={saving||!isDirty}>{saving?'Salvando…':'Salvar rascunho'}</button><button className="primary" onClick={()=>save(true)} disabled={saving||!canApprove||!approvalStageReady} title={!canApprove?'Seu perfil não possui permissão para aprovar.':!approvalStageReady?'Projeto fora da etapa de aprovação.':''}>Aprovar planejamento</button></>}</div>
    </>}
    </div></section></div>,document.body)}
  </section>
}

function ConfiguredInput({field,value,onChange}){
  const label=field.label+(field.required?' *':'');
  if(field.field_type==='textarea')return <label className="core-field is-wide"><span>{label}</span><textarea required={field.required} value={value??''} onChange={event=>onChange(event.target.value)}/></label>;
  if(field.field_type==='select')return <label className="core-field"><span>{label}</span><select required={field.required} value={value??''} onChange={event=>onChange(event.target.value)}><option value="">Selecione</option>{(field.options||[]).map(option=><option key={option} value={option}>{option}</option>)}</select></label>;
  if(field.field_type==='checkbox')return <label className="core-toggle"><input type="checkbox" checked={!!value} onChange={event=>onChange(event.target.checked)}/><span>{label}</span></label>;
  return <label className="core-field"><span>{label}</span><input type={field.field_type==='phone'?'tel':field.field_type||'text'} required={field.required} value={value??''} onChange={event=>onChange(event.target.value)}/></label>;
}
function CoreInput({label,value,onChange,type='text',wide=false,required=false,placeholder=''}){return <label className={`core-field ${wide?'is-wide':''}`}><span>{label}{required?' *':''}</span><input type={type} required={required} value={value??''} placeholder={placeholder} onChange={event=>onChange(event.target.value)}/></label>}

function ProjectCoreAdmin({project,fields=[],inventoryTypes=[],onSave}){
  const [open,setOpen]=useState(false);const [saving,setSaving]=useState(false);
  const makeDraft=()=>({company_name:project.company_name||'',trade_name:project.trade_name||'',address:project.address||'',contact_name:project.primary_contact?.name||'',contact_email:project.primary_contact?.email||'',contact_phone:project.primary_contact?.phone||'',inventory_type:project.inventory_type||'',layout_system:project.layout_system||'',ti_contact_name:project.ti_contact_name||'',ti_contact_email:project.ti_contact_email||'',ti_contact_phone:project.ti_contact_phone||'',operational_notes:project.operational_notes||'',custom:Object.fromEntries(fields.filter(field=>!field.system_field).map(field=>[field.id,project[field.field_key]??'']))});
  const [draft,setDraft]=useState(makeDraft);useEffect(()=>{setDraft(makeDraft());setOpen(false)},[project.id,project.updated_at]);const set=(key,value)=>setDraft(current=>({...current,[key]:value}));const reset=()=>{setDraft(makeDraft());setOpen(false)};
  async function submit(event){event.preventDefault();setSaving(true);try{await onSave?.({project_id:project.id,expected_updated_at:project.updated_at,client:{legal_name:draft.company_name,trade_name:draft.trade_name,address:draft.address},contact:{name:draft.contact_name,email:draft.contact_email,phone:draft.contact_phone},project:{inventory_type:draft.inventory_type,layout_system:draft.layout_system,ti_contact_name:draft.ti_contact_name,ti_contact_email:draft.ti_contact_email,ti_contact_phone:draft.ti_contact_phone,operational_notes:draft.operational_notes},field_values:fields.filter(field=>field.active&&!field.system_field).map(field=>({field_id:field.id,value:draft.custom[field.id]}))});setOpen(false)}finally{setSaving(false)}}
  const locked=['confirmed','cancelled'].includes(project.status);const customFields=fields.filter(field=>field.active&&!field.system_field);
  return <section className={`card project-core-admin ${open?'is-open':''}`}>
    <div className="core-admin-summary"><div className="core-admin-icon">CI</div><div className="core-admin-copy"><span className="eyebrow">Cadastro da operação</span><h3>Cliente, contatos e configuração</h3><p>{locked?'Este cadastro está protegido porque a operação foi concluída ou cancelada.':'Revise os dados-base usados em todas as etapas do inventário.'}</p><div className="core-admin-facts"><span>{project.inventory_type||'Tipo não informado'}</span><span>{project.layout_system||'Sistema não informado'}</span><span>{project.primary_contact?.name||'Contato não informado'}</span></div></div><button type="button" className={open?'core-close':''} disabled={locked} onClick={()=>open?reset():setOpen(true)}>{open?'Fechar edição':'Editar cadastro'}</button></div>
    {open&&<form className="core-admin-form" onSubmit={submit}>
      <section className="core-form-section"><div className="core-section-title"><span>1</span><div><h4>Identificação da unidade</h4><p>Dados da empresa e do local onde o inventário será realizado.</p></div></div><div className="core-form-grid"><CoreInput label="Razão social" required wide value={draft.company_name} onChange={value=>set('company_name',value)}/><CoreInput label="Nome fantasia" value={draft.trade_name} onChange={value=>set('trade_name',value)}/><CoreInput label="Endereço completo" wide value={draft.address} onChange={value=>set('address',value)}/></div></section>
      <section className="core-form-section"><div className="core-section-title"><span>2</span><div><h4>Configuração operacional</h4><p>Define regras, tarefas e preparação técnica aplicáveis.</p></div></div><div className="core-form-grid two"><label className="core-field"><span>Tipo de inventário</span><select value={draft.inventory_type} onChange={event=>set('inventory_type',event.target.value)}><option value="">Selecione</option>{inventoryTypes.filter(item=>item.active).map(item=><option key={item.id} value={item.name}>{item.name}</option>)}</select></label><CoreInput label="Layout / sistema" value={draft.layout_system} onChange={value=>set('layout_system',value)}/></div></section>
      <section className="core-contact-grid"><div className="core-contact-card"><div><span className="core-contact-badge">Principal</span><h4>Contato da unidade</h4></div><CoreInput label="Nome" value={draft.contact_name} onChange={value=>set('contact_name',value)}/><CoreInput label="E-mail" type="email" value={draft.contact_email} onChange={value=>set('contact_email',value)}/><CoreInput label="Telefone" type="tel" value={draft.contact_phone} onChange={value=>set('contact_phone',value)}/></div><div className="core-contact-card is-ti"><div><span className="core-contact-badge">TI</span><h4>Contato técnico</h4></div><CoreInput label="Nome" value={draft.ti_contact_name} onChange={value=>set('ti_contact_name',value)}/><CoreInput label="E-mail" type="email" value={draft.ti_contact_email} onChange={value=>set('ti_contact_email',value)}/><CoreInput label="Telefone" type="tel" value={draft.ti_contact_phone} onChange={value=>set('ti_contact_phone',value)}/></div></section>
      {customFields.length>0&&<section className="core-form-section"><div className="core-section-title"><span>3</span><div><h4>Campos adicionais</h4><p>Informações configuradas pela Administração.</p></div></div><div className="core-form-grid">{customFields.map(field=><ConfiguredInput key={field.id} field={field} value={draft.custom[field.id]} onChange={value=>setDraft(current=>({...current,custom:{...current.custom,[field.id]:value}}))}/>)}</div></section>}
      <section className="core-form-section"><div className="core-section-title"><span>{customFields.length?4:3}</span><div><h4>Observações operacionais</h4><p>Registre exceções, acordos e contexto que a equipe precisa conhecer.</p></div></div><label className="core-field is-wide"><span>Observações</span><textarea value={draft.operational_notes} placeholder="Adicione orientações relevantes para a operação…" onChange={event=>set('operational_notes',event.target.value)}/></label></section>
      <footer className="core-form-actions"><button type="button" onClick={reset}>Cancelar</button><button className="primary" disabled={saving}>{saving?'Salvando…':'Salvar cadastro'}</button></footer>
    </form>}
  </section>
}

function LifecycleControls({project,stages=[],onAction}){const [busy,setBusy]=useState(false);const customStages=stages.filter(stage=>stage.active&&!stage.system_stage);async function run(action,options={}){if(busy)return;setBusy(true);try{await onAction?.(project.id,action,options)}finally{setBusy(false)}}async function withReason(action,label){const reason=window.prompt(`Motivo para ${label.toLowerCase()}:`);if(reason===null)return;if(!reason.trim())return window.alert('Informe um motivo para manter a trilha de auditoria.');await run(action,{reason:reason.trim()})}return <section className="card lifecycle-controls"><div><span className="eyebrow">Administração</span><h3>Lifecycle e etapa adicional</h3><p>Etapas adicionais não alteram os gates obrigatórios da operação.</p></div><select aria-label="Etapa adicional" value={project.workflow_stage_key||''} disabled={busy} onChange={event=>event.target.value?run('set_custom_stage',{stage_key:event.target.value}):run('clear_custom_stage')}><option value="">Fluxo operacional padrão</option>{customStages.map(stage=><option key={stage.stage_key} value={stage.stage_key}>{stage.label}</option>)}</select><div className="admin-actions">{project.status!=='confirmed'&&project.status!=='cancelled'&&<button type="button" disabled={busy} onClick={()=>withReason('cancel','cancelar')}>Cancelar operação</button>}<button type="button" className="delete" disabled={busy} onClick={()=>withReason('archive','arquivar')}>Arquivar operação</button></div></section>}

function PlanningKanban({projects,stages=[],selectedId,onSelect,edit,canDimension=false,canApproveTi=false}){
  const [search,setSearch]=useState('');const [pendingAction,setPendingAction]=useState('');const normalizedSearch=search.trim().toLocaleLowerCase('pt-BR');const active=projects.filter(item=>item.status!=='cancelled');const filtered=normalizedSearch?active.filter(item=>[item.company_name,item.trade_name,item.cnpj,item.reference,item.inventory_type].filter(Boolean).some(value=>String(value||'').toLocaleLowerCase('pt-BR').includes(normalizedSearch))):active;const customColumns=stages.filter(stage=>stage.active&&!stage.system_stage).map(stage=>({key:stage.stage_key,label:stage.label,statuses:[],custom:true}));const activeCustomKeys=new Set(customColumns.map(column=>column.key));const columns=[...planningColumns.slice(0,-1),...customColumns,planningColumns.at(-1)];
  async function action(item,patch,message,confirmation){if(confirmation&&!window.confirm(confirmation))return;const actionKey=`${item.id}:${patch.status||'update'}`;setPendingAction(actionKey);try{await edit?.(item.id,patch,message)}finally{setPendingAction('')}}
  return <section className="planning-kanban"><div className="kanban-heading"><div><span className="eyebrow">Fluxo único operacional</span><h2>Inventários em movimento</h2><p>Entrada, dimensionamento, TI, planejamento e conclusão no mesmo Kanban. Abra um cartão para trabalhar na etapa atual.</p><div className="kanban-search"><input aria-label="Pesquisar inventários" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Pesquisar empresa, CNPJ ou referência"/>{search&&<button type="button" onClick={()=>setSearch('')}>Limpar</button>}</div></div><span className="kanban-total">{filtered.length} {filtered.length===1?'inventário':'inventários'}</span></div><div className="kanban-board">{columns.map(column=>{const items=filtered.filter(item=>column.custom?item.workflow_stage_key===column.key:(!item.workflow_stage_key||!activeCustomKeys.has(item.workflow_stage_key))&&column.statuses.includes(item.status));return <div className={`kanban-column kanban-column-${column.key}`} key={column.key}><div className="kanban-column-head"><div><span className="kanban-dot"/><b>{column.label}</b></div><span>{items.length}</span></div><div className="kanban-cards">{items.length?items.map(item=>{const planningContent=item.planning?.content||{};const itemAudit=auditPlanning(planningContent);const store=planningContent.store||{};const datesLabel=store.inventoryStart&&store.inventoryEnd?`${formatDate(store.inventoryStart)} – ${formatDate(store.inventoryEnd)}`:'Período não definido';const pending=item.planning?itemAudit.approvalIssues.length:null;const busy=pendingAction.startsWith(item.id);const approvedDimension=(item.dimensioning_options||[]).find(option=>option.approved);const openTasks=(item.project_tasks||[]).filter(task=>!['completed','waived'].includes(task.status));const taskPending=openTasks.length;const cardPendencies=[...openTasks.map(task=>({id:`task-${task.id}`,label:task.title,meta:[task.responsible_name||task.responsible_role||'Sem responsável',task.due_at?`Prazo ${formatDateTime(task.due_at)}`:'Sem prazo'].join(' · ')})),...(item.planning?itemAudit.approvalIssues.map((issue,index)=>({id:`audit-${index}-${issue}`,label:issue,meta:'Planejamento'})):[])];return <article className={`kanban-card ${selectedId===item.id?'is-selected':''}`} key={item.id} onClick={event=>onSelect(item.id,event.currentTarget)}><div className="kanban-card-top"><span className="kanban-reference">{item.reference||'Sem referência'}</span><span className={`kanban-status kanban-status-${item.status}`}>{planningStatus[item.status]||item.status}</span></div><div className="kanban-card-title-row"><h3>{item.company_name||'Cliente sem cadastro'}</h3><button type="button" className="kanban-card-select" aria-pressed={selectedId===item.id} aria-label={`Abrir operação ${item.company_name}`} onClick={event=>{event.stopPropagation();onSelect(item.id,event.currentTarget)}}>Abrir</button></div><p className="kanban-meta">{store.unit||item.inventory_type||'Unidade não definida'}</p><div className="kanban-card-info"><span><b>Período</b>{datesLabel}</span><span><b>{item.status==='awaiting_dimensioning'?'Opção':'Dias'}</b>{item.status==='awaiting_dimensioning'?(approvedDimension?.title||'Não escolhida'):(planningContent.days?.length||0)}</span></div><div className="kanban-progress-line"><i style={{width:`${itemAudit.percentage}%`}}/></div><div className="kanban-card-bottom"><span>{taskPending?`${taskPending} tarefa(s) aberta(s)`:item.planning?`${itemAudit.percentage}% preenchido`:'Planejamento será iniciado após o gate'}</span>{pending===null?<span className="kanban-pending neutral">Ação necessária</span>:pending>0?<span className="kanban-pending">{pending} pendência(s)</span>:<span className="kanban-pending ready">Pronto</span>}</div>{cardPendencies.length>0&&<details className="kanban-pending-details" onClick={event=>event.stopPropagation()}><summary><span>Ver pendências</span><b>{cardPendencies.length}</b></summary><ul>{cardPendencies.slice(0,5).map(pendency=><li key={pendency.id}><span>{pendency.label}</span><small>{pendency.meta}</small></li>)}</ul>{cardPendencies.length>5&&<p>+ {cardPendencies.length-5} pendência(s) dentro da operação</p>}</details>}<div className="kanban-card-actions" onClick={event=>event.stopPropagation()}>{item.status==='received'&&<button type="button" disabled={!canDimension||busy} onClick={()=>action(item,{status:'awaiting_dimensioning'},'Dimensionamento iniciado no Planejamento','Iniciar o dimensionamento desta operação?')}>{busy?'Processando…':'Iniciar dimensionamento'}</button>}{item.status==='awaiting_dimensioning'&&<button type="button" disabled={!canDimension} onClick={event=>onSelect(item.id,event.currentTarget)}>Abrir dimensionamento</button>}{item.status==='awaiting_ti'&&<button type="button" disabled={!canApproveTi} onClick={event=>onSelect(item.id,event.currentTarget)}>Abrir validação de TI</button>}{item.status==='awaiting_dates'&&<button type="button" onClick={event=>onSelect(item.id,event.currentTarget)}>Abrir planejamento</button>}{item.status==='planning'&&<button type="button" onClick={event=>onSelect(item.id,event.currentTarget)}>Abrir planejamento</button>}{item.status==='confirmed'&&<button type="button" onClick={event=>onSelect(item.id,event.currentTarget)}>Consultar planejamento</button>}</div></article>}):<div className="kanban-empty">Nenhum inventário nesta etapa.</div>}</div></div>})}</div></section>
}

function DimensioningPanel({project,draft,setDraft,dirty,saving,canDimension,notice,onSave,onComplete}){
  const updateOption=(id,patch)=>setDraft(current=>({...current,options:current.options.map(option=>option.id===id?{...option,...patch}:option)}));const addOption=()=>setDraft(current=>({...current,options:[...current.options,dimensionOption(`Opção ${current.options.length+1}`)]}));const removeOption=id=>{const option=draft.options.find(item=>item.id===id);if(option&&hasRowData(option,['id'])&&!window.confirm('Excluir esta opção de dimensionamento preenchida?'))return;setDraft(current=>({...current,options:current.options.filter(item=>item.id!==id),selected_option_id:current.selected_option_id===id?'':current.selected_option_id}))};const updateVisit=(index,value)=>setDraft(current=>({...current,visit_starts:current.visit_starts.map((item,itemIndex)=>itemIndex===index?value:item)}));
  return <div className="dimension-workspace"><fieldset className="stage-form-fieldset" disabled={!canDimension}><section className="card dimension-overview"><div><span className="eyebrow">Dimensionamento completo</span><h2>Compare cenários e aprove uma opção</h2><p>Registre quantos dias e pessoas cada cenário exige. A opção escolhida seguirá para o Planejamento; as datas abaixo são somente para a visita de dimensionamento.</p></div><div className="dimension-kpis"><span><small>Cenários</small><b>{draft.options.length}</b></span><span><small>Escolhido</small><b>{draft.options.find(option=>option.id===draft.selected_option_id)?.title||'Pendente'}</b></span><span><small>Visitas</small><b>{draft.visit_starts.filter(Boolean).length}/2</b></span></div></section><section className="card dimension-options"><div className="section-heading"><div><span className="eyebrow">Cenários operacionais</span><h2>Opções de dimensionamento</h2></div><button type="button" onClick={addOption} disabled={!canDimension}>+ Adicionar opção</button></div><div className="dimension-option-list">{draft.options.map((option,index)=><article className={`dimension-option ${draft.selected_option_id===option.id?'is-approved':''}`} key={option.id}><label className="dimension-approve"><input type="radio" name={`dimension-${project.id}`} checked={draft.selected_option_id===option.id} onChange={()=>setDraft(current=>({...current,selected_option_id:option.id}))}/><span>Aprovar esta opção</span></label><div className="grid"><Input label="Nome da opção" value={option.title} onChange={value=>updateOption(option.id,{title:value})}/><Input label="Quantidade de dias" type="number" value={option.days} onChange={value=>updateOption(option.id,{days:value})}/><Input label="Tamanho da equipe" type="number" value={option.team_size} onChange={value=>updateOption(option.id,{team_size:value})}/></div><Text label="Premissas e observações" value={option.notes} onChange={value=>updateOption(option.id,{notes:value})}/><button type="button" className="delete" onClick={()=>removeOption(option.id)} disabled={draft.options.length<=1}>Excluir opção {index+1}</button></article>)}</div></section><section className="card dimension-visits"><div className="section-heading"><div><span className="eyebrow">Pré-visita</span><h2>Opções para a visita de dimensionamento</h2><p>Essas datas não são as datas do inventário. A confirmação da visita acontecerá no gate de TI/Datas.</p></div></div><div className="grid"><Input label="Primeira opção de visita" type="datetime-local" value={draft.visit_starts[0]} onChange={value=>updateVisit(0,value)}/><Input label="Segunda opção de visita" type="datetime-local" value={draft.visit_starts[1]} onChange={value=>updateVisit(1,value)}/></div><Text label="Observações do dimensionamento" value={draft.notes} onChange={value=>setDraft(current=>({...current,notes:value}))}/></section></fieldset><div className="sticky-actions dimension-actions"><span>{notice||(!canDimension?'Seu perfil não possui permissão para editar o dimensionamento.':dirty?'Há alterações não salvas.':'Rascunho salvo.')}</span><button type="button" onClick={onSave} disabled={saving||!canDimension||!dirty}>{saving?'Salvando…':'Salvar rascunho'}</button><button type="button" className="primary" onClick={onComplete} disabled={saving||!canDimension}>{saving?'Concluindo…':'Concluir e encaminhar para TI'}</button></div></div>
}

function ProjectTasksPanel({project,canManage,onUpdateTask,onSyncTasks}){
  const [saving,setSaving]=useState('');const tasks=project.project_tasks||[];async function update(task,patch){setSaving(task.id);try{await onUpdateTask?.(project.id,task.id,patch)}finally{setSaving('')}}async function sync(){setSaving('sync');try{await onSyncTasks?.(project.id,project.planning?.content?.store?.inventoryStart||null)}finally{setSaving('')}}return <section className="card project-tasks"><div className="section-heading"><div><span className="eyebrow">Lista do serviço</span><h2>Tarefas desta operação</h2><p>Geradas pelos modelos do tipo de inventário e resumidas diretamente no card desta operação no Kanban.</p></div>{canManage&&<button type="button" onClick={sync} disabled={saving==='sync'}>{saving==='sync'?'Sincronizando…':'Sincronizar modelos'}</button>}</div>{tasks.length?<div className="project-task-list">{tasks.map(task=><ProjectTaskRow key={task.id} task={task} canManage={canManage} saving={saving===task.id} onUpdate={patch=>update(task,patch)}/>)}</div>:<div className="project-task-empty"><b>Nenhuma tarefa gerada para este serviço.</b><span>Cadastre modelos em Configurações e sincronize. A lista oficial do Notion ainda está pendente da Contagem.</span></div>}</section>
}
function ProjectTaskRow({task,canManage,saving,onUpdate}){const [responsible,setResponsible]=useState(task.responsible_name||'');const [due,setDue]=useState(toLocalDateTime(task.due_at));useEffect(()=>{setResponsible(task.responsible_name||'');setDue(toLocalDateTime(task.due_at))},[task.responsible_name,task.due_at,task.updated_at]);return <article className={['completed','waived'].includes(task.status)?'is-completed':''}><div><b>{task.title}</b><span>{task.description||task.responsible_role||'Sem descrição'}</span></div><label>Responsável<input value={responsible} disabled={!canManage||saving} onChange={event=>setResponsible(event.target.value)} onBlur={()=>{if(responsible!==(task.responsible_name||''))onUpdate({responsible_name:responsible||null})}}/></label><label>Prazo<input type="datetime-local" value={due} disabled={!canManage||saving} onChange={event=>setDue(event.target.value)} onBlur={()=>{const value=toIsoDateTime(due)||null;const nextTime=value?new Date(value).getTime():null;const currentTime=task.due_at?new Date(task.due_at).getTime():null;if(nextTime!==currentTime)onUpdate({due_at:value,due_overridden:true})}}/></label><label>Status<select value={task.status} disabled={!canManage||saving} onChange={event=>onUpdate({status:event.target.value,completed_at:event.target.value==='completed'?new Date().toISOString():null})}><option value="pending">Pendente</option><option value="in_progress">Em andamento</option><option value="completed">Concluída</option><option value="waived">Dispensada</option></select></label></article>}

function DimensioningSummary({project}){const approved=(project.dimensioning_options||[]).find(option=>option.approved);if(!approved)return null;return <section className="card dimension-history"><div><span className="eyebrow">Dimensionamento aprovado</span><h3>{approved.title}</h3></div><div><span><small>Duração</small><b>{approved.days||'—'} dia(s)</b></span><span><small>Equipe</small><b>{approved.team_size||'—'} pessoa(s)</b></span><span><small>Aprovação</small><b>{approved.approved_at?formatDateTime(approved.approved_at):'Registrada'}</b></span></div>{approved.details?.notes&&<p>{approved.details.notes}</p>}</section>}

function TiValidationPanel({project,draft,setDraft,selectedVisitId,setSelectedVisitId,dirty,saving,canApproveTi,notice,onSave,onApprove}){
  const options=project.date_option_records||[];
  const update=(key,value)=>setDraft(current=>({...current,[key]:value}));
  return <div className="ti-workspace"><fieldset className="stage-form-fieldset" disabled={!canApproveTi}><section className="card ti-overview"><div><span className="eyebrow">Gate técnico</span><h2>TI e confirmação da visita</h2><p>Os dados vieram da solicitação comercial. Revise, complete e selecione a data de visita acordada antes de liberar o planejamento.</p></div><div className="ti-overview-grid"><span><small>Sistema recebido</small><b>{project.layout_system||'Não informado'}</b></span><span><small>Contato recebido</small><b>{project.ti_contact_name||'Não informado'}</b></span><span><small>Opções de visita</small><b>{options.length}</b></span></div></section><section className="card ti-form-card"><div className="section-heading"><div><span className="eyebrow">Dados técnicos</span><h2>Validação de TI</h2></div><span className={`save-state ${dirty?'is-dirty':'is-saved'}`}>{dirty?'Alterações não salvas':'Rascunho salvo'}</span></div><div className="grid"><Input label="Sistema / layout validado *" value={draft.system_name} onChange={value=>update('system_name',value)}/><Input label="Contato TI — nome *" value={draft.ti_contact_name} onChange={value=>update('ti_contact_name',value)}/><Input label="Contato TI — e-mail *" type="email" value={draft.ti_contact_email} onChange={value=>update('ti_contact_email',value)}/><Input label="Contato TI — telefone" type="tel" value={draft.ti_contact_phone} onChange={value=>update('ti_contact_phone',value)}/></div><Text label="Observações técnicas" value={draft.notes} onChange={value=>update('notes',value)}/></section><section className="card visit-selection"><div className="section-heading"><div><span className="eyebrow">Data separada do inventário</span><h2>Visita de dimensionamento</h2><p>Escolha a opção confirmada para a visita. A data efetiva do inventário continuará sendo definida no planejamento.</p></div>{selectedVisitId&&<span className="visit-selected-badge">Opção selecionada</span>}</div>{options.length?<div className="visit-options">{options.map(option=><label className={`visit-option ${selectedVisitId===option.id?'is-selected':''}`} key={option.id}><input type="radio" name={`visit-${project.id}`} value={option.id} checked={selectedVisitId===option.id} onChange={()=>setSelectedVisitId(option.id)}/><span><b>Opção {option.option_number}</b><strong>{formatDateTime(option.starts_at)}</strong><small>{option.status==='selected'?'Confirmada':'Proposta'}{option.sent_at?` · enviada em ${formatDateTime(option.sent_at)}`:''}</small></span></label>)}</div>:<div className="ti-blocker"><b>Nenhuma opção de visita foi registrada.</b><span>Volte ao Dimensionamento, informe as opções e conclua a etapa novamente.</span></div>}</section>{project.ti_validation?.validated_at&&<TiApprovalHistory project={project}/>}</fieldset><div className="sticky-actions ti-actions"><span>{notice||(!canApproveTi?'Seu perfil não possui permissão para validar TI.':dirty?'Há alterações não salvas.':'Revise os campos e confirme a visita antes de aprovar.')}</span><button type="button" onClick={onSave} disabled={saving||!canApproveTi||!dirty}>{saving?'Salvando…':'Salvar rascunho'}</button><button type="button" className="primary" onClick={onApprove} disabled={saving||!canApproveTi}>{saving?'Validando…':'Validar TI e liberar planejamento'}</button></div></div>
}
function TiApprovalHistory({project}){const ti=project.ti_validation||{};const selected=(project.date_option_records||[]).find(option=>option.id===project.selected_date_option_id||option.status==='selected');return <section className="card ti-history"><div><span className="eyebrow">Histórico do gate</span><h3>TI validada</h3></div><div className="ti-history-grid"><span><small>Sistema</small><b>{ti.system_name||project.layout_system||'Não informado'}</b></span><span><small>Contato</small><b>{ti.ti_contact_name||project.ti_contact_name||'Não informado'}</b></span><span><small>Visita confirmada</small><b>{selected?formatDateTime(selected.starts_at):'Não registrada'}</b></span><span><small>Validação</small><b>{ti.validated_at?formatDateTime(ti.validated_at):ti.status||'Pendente'}</b></span></div>{ti.notes&&<p>{ti.notes}</p>}</section>}

function AuditSummary({audit,onNavigate}){return <div className={`audit-summary ${audit.approvalReady?'is-ready':'has-pending'}`}><div className="audit-summary-head"><div><h3>{audit.approvalReady?'Planejamento pronto para aprovação':'Pendências por bloco'}</h3><p>{audit.approvalReady?'Todos os blocos aplicáveis e checklists estão completos.':`${audit.approvalIssues.length} pendência(s) precisam de atenção antes da aprovação.`}</p></div>{audit.validationErrors.length>0&&<span className="audit-warning">{audit.validationErrors.length} inconsistência(s)</span>}</div>{audit.pendingBlocks.length>0&&<div className="audit-blocks">{audit.pendingBlocks.map(block=><article key={block.key} className="audit-block-link" role="button" tabIndex={0} onClick={()=>onNavigate?.(block.key)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();onNavigate?.(block.key)}}}><div><b>{block.label}</b><span>{block.percentage}%</span></div><ul>{block.issues.slice(0,4).map(issue=><li key={issue}>{issue}</li>)}</ul>{block.issues.length>4&&<small>+ {block.issues.length-4} pendência(s) neste bloco</small>}<em>Ir para o bloco</em></article>)}</div>}</div>}
function Block({blockKey,title,subtitle,children,completed=false,onToggle,readOnly=false,active=true}){const [expanded,setExpanded]=useState(!completed);useEffect(()=>{if(!completed)setExpanded(true)},[completed]);if(!active)return null;const handleToggle=()=>{if(readOnly){setExpanded(current=>!current);return}onToggle?.();setExpanded(completed)};return <section id={blockKey} className={`card plan-block ${completed?'is-completed':''} ${readOnly?'is-readonly':''}`}><div className="plan-block-header"><div className="plan-block-title"><h2>{completed&&<span className="block-check" aria-hidden="true">✓</span>}{title}</h2>{(!completed||expanded)&&subtitle&&<p>{subtitle}</p>}</div><div className="plan-block-controls">{completed&&<span className="block-complete-label">Concluído</span>}{!readOnly&&<button type="button" className="block-complete-button" onClick={handleToggle}>{completed?'Reabrir bloco':'Concluir bloco'}</button>}</div></div>{completed&&!expanded?<button type="button" className="block-collapsed-summary" onClick={()=>setExpanded(true)}><span>✓ Bloco concluído</span><span>Expandir para consultar</span></button>:<fieldset className="plan-block-body" disabled={readOnly}>{children}</fieldset>}</section>}
function Input({label,value,onChange,type='text',list,min}){const minimum=type==='number'?(min??1):min;return <label>{label}<input list={list} type={type} min={minimum} value={value??''} onChange={event=>onChange(event.target.value)}/></label>}
function Text({label,value,onChange}){return <label className="text-area">{label}<textarea value={value??''} onChange={event=>onChange(event.target.value)} placeholder="Insira os detalhes necessários…"/></label>}
function Toggle({label,checked,onChange}){return <label className="toggle"><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)}/>{label}</label>}
function Rows({rows,add,remove,children,isFilled=hasRowData}){const removeRow=index=>{if(confirmFilledRemoval(rows[index],'esta linha',isFilled))remove(index)};return <div className="rows">{rows.map((item,index)=><div className="dynamic-row" key={item.id||index}>{children(item,index)}<button className="delete" onClick={()=>removeRow(index)}>Excluir linha</button></div>)}<button onClick={add}>+ Adicionar linha</button></div>}
function Equipment({blockKey,completed,onToggle,title,value,path,setContent,readOnly=false,active=true}){const add=()=>setContent(current=>{const next=structuredClone(current);next[path].rows.push({id:uid(),equipment:'',date:'',shift:'',quantity:'',status:'Solicitado',notes:''});return next});const remove=index=>setContent(current=>{const next=structuredClone(current);next[path].rows.splice(index,1);return next});const row=(index,key,value)=>setContent(current=>{const next=structuredClone(current);next[path].rows[index][key]=value;return next});const notes=value=>setContent(current=>{const next=structuredClone(current);next[path].notes=value;return next});return <Block active={active} readOnly={readOnly} blockKey={blockKey} completed={completed} onToggle={onToggle} title={title} subtitle="Por item, dia e turno"><Rows rows={value.rows} add={add} remove={remove}>{(item,index)=><div className="row-grid four"><Input label="Equipamento" list="equipment" value={item.equipment} onChange={next=>row(index,'equipment',next)}/><Input label="Dia" type="date" value={item.date} onChange={next=>row(index,'date',next)}/><Input label="Turno" value={item.shift} onChange={next=>row(index,'shift',next)}/><Input label="Quantidade" type="number" value={item.quantity} onChange={next=>row(index,'quantity',next)}/><Input label="Status" value={item.status} onChange={next=>row(index,'status',next)}/><Input label="Observação" value={item.notes} onChange={next=>row(index,'notes',next)}/></div>}</Rows><Text label="Detalhes do bloco" value={value.notes} onChange={notes}/></Block>}
function DayEditor({day:dayItem,index,setContent,removeDay}){const setDay=(key,value)=>setContent(current=>{const next=structuredClone(current);next.days[index][key]=value;return next});const addArea=kind=>setContent(current=>{const next=structuredClone(current);next.days[index].areas.push(area(kind));return next});const confirmRemove=()=>{if(confirmFilledRemoval(dayItem,'este dia',item=>hasRowData(item)))removeDay()};return <div className="day-card"><div className="day-head"><div><h3>Dia {index+1}</h3><small>{dayItem.date?`${formatWeekday(dayItem.date)} · ${formatDate(dayItem.date)}`:'Data não informada'}</small></div><button className="delete" onClick={confirmRemove}>Excluir dia</button></div><div className="grid"><Input label="Data" type="date" value={dayItem.date} onChange={value=>setDay('date',value)}/><Input label="Equipe prevista" type="number" value={dayItem.headcount} onChange={value=>setDay('headcount',value)}/></div><Text label="Observações do dia" value={dayItem.notes} onChange={value=>setDay('notes',value)}/>{(dayItem.areas||[]).map((areaItem,areaIndex)=><AreaEditor key={areaItem.id||areaIndex} area={areaItem} dayIndex={index} areaIndex={areaIndex} setContent={setContent}/>) }<div className="area-templates"><button onClick={()=>addArea('Depósito')}>+ Depósito</button><button onClick={()=>addArea('Câmaras')}>+ Câmaras</button><button onClick={()=>addArea('Coordenação')}>+ Coordenação</button><button onClick={()=>addArea('Divisão da equipe')}>+ Divisão da equipe</button><button onClick={()=>addArea('Outro turno / área')}>+ Outro</button></div></div>}
function AreaEditor({area:areaItem,dayIndex,areaIndex,setContent}){const update=(key,value)=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex][key]=value;return next});const addRole=()=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].roles.push({id:uid(),role:'',count:'',names:''});return next});const addAct=()=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].activities.push({id:uid(),name:'',notes:''});return next});const delArea=()=>{if(!confirmFilledRemoval(areaItem,'esta área'))return;setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas.splice(areaIndex,1);return next})};const removeRole=roleIndex=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].roles.splice(roleIndex,1);return next});const removeActivity=activityIndex=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].activities.splice(activityIndex,1);return next});return <div className="area-card"><div className="day-head"><h3>{areaItem.name||'Área / turno'}</h3><button className="delete" onClick={delArea}>Excluir área</button></div><div className="grid"><Input label="Área" value={areaItem.name} onChange={value=>update('name',value)}/><Input label="Turno" value={areaItem.shift} onChange={value=>update('shift',value)}/><Input label="Início" type="time" value={areaItem.startsAt} onChange={value=>update('startsAt',value)}/><Input label="Equipe prevista" type="number" value={areaItem.headcount} onChange={value=>update('headcount',value)}/></div><h4>Equipe</h4><Rows rows={areaItem.roles||[]} add={addRole} remove={removeRole}>{(roleItem,roleIndex)=><div className="row-grid"><Input label="Função" list="roles" value={roleItem.role} onChange={value=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].roles[roleIndex].role=value;return next})}/><Input label="Quantidade" type="number" value={roleItem.count} onChange={value=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].roles[roleIndex].count=value;return next})}/><Input label="Nomes" value={roleItem.names} onChange={value=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].roles[roleIndex].names=value;return next})}/></div>}</Rows><h4>Atividades</h4><Rows rows={areaItem.activities||[]} add={addAct} remove={removeActivity}>{(activity,activityIndex)=><div className="row-grid"><Input label="Atividade" list="activities" value={activity.name} onChange={value=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].activities[activityIndex].name=value;return next})}/><Input label="Observação da atividade" value={activity.notes} onChange={value=>setContent(current=>{const next=structuredClone(current);next.days[dayIndex].areas[areaIndex].activities[activityIndex].notes=value;return next})}/></div>}</Rows><Text label="Detalhes da área" value={areaItem.notes} onChange={value=>update('notes',value)}/></div>}
function Checklist({anchorId,title,subtitle,deadline,items,userId,onChange}){const recommended=deadline?new Date(new Date(`${deadline}T12:00:00`).getTime()-3*86400000).toLocaleDateString('pt-BR'):'';const limit=deadline?new Date(new Date(`${deadline}T12:00:00`).getTime()-86400000).toLocaleDateString('pt-BR'):'';const toggle=(item,index,done)=>onChange(items.map((current,currentIndex)=>{if(currentIndex!==index)return current;if(done)return {...current,done:true,completedAt:new Date().toISOString(),completedBy:userId||null};const {completedAt,completedBy,...reopened}=current;return {...reopened,done:false}}));const removeItem=index=>{const item=items[index];if(!confirmFilledRemoval(item,'este item de checklist',current=>hasValue(current?.label)||current?.done))return;onChange(items.filter((_,currentIndex)=>currentIndex!==index))};return <div id={anchorId} className="checklist"><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}{deadline&&<small className="check-deadline">{limit?`Prazo: ${limit} · Recomendado: ${recommended}`:'Defina a data do inventário para calcular o prazo.'}</small>}{items.map((item,index)=><div className={`check-item ${item.done?'is-done':''}`} key={item.id||index}><input type="checkbox" checked={Boolean(item.done)} onChange={event=>toggle(item,index,event.target.checked)}/><input aria-label="Item do checklist" value={item.label??''} onChange={event=>onChange(items.map((current,currentIndex)=>currentIndex===index?{...current,label:event.target.value}:current))}/><button className="delete" onClick={()=>removeItem(index)}>Excluir</button></div>)}<button onClick={()=>onChange([...items,{id:uid(),label:'',done:false}])}>+ Adicionar item</button></div>}
export function PlanningLists({catalogs={}}){const roleOptions=catalogs.roles?.length?catalogs.roles:roles;const activityOptions=catalogs.activities?.length?catalogs.activities.map(item=>item.name):activities;const equipmentOptions=catalogs.equipment?.length?catalogs.equipment.map(item=>item.name):equipment;return <><datalist id="roles">{roleOptions.map(item=><option key={item} value={item}/>)}</datalist><datalist id="activities">{activityOptions.map(item=><option key={item} value={item}/>)}</datalist><datalist id="equipment">{equipmentOptions.map(item=><option key={item} value={item}/>)}</datalist></>}
